INSERT INTO TarotCards (id, title, arcana, image, description, sortOrder, lastUpdated) VALUES
  ('fool', 'The Fool', 'Major Arcana', 'cards/fool.jpg', 'A leap of faith into the unknown. The Fool stands at the edge of a cliff with only a small bag and a dog at his heels, ready to begin a journey full of possibility and innocent trust.', 0, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('magician', 'The Magician', 'Major Arcana', 'cards/magician.jpg', 'Manifestation and resourcefulness. With one hand raised to heaven and one pointing to earth, the Magician shows you already hold every tool needed to turn an idea into reality.', 1, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('high-priestess', 'The High Priestess', 'Major Arcana', 'cards/high-priestess.jpg', 'Intuition, mystery, and inner knowledge. Seated between the black and white pillars, she guards the secrets that surface when you trust your instincts over what is obvious.', 2, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('empress', 'The Empress', 'Major Arcana', 'cards/empress.jpg', 'Abundance, fertility, and nurturing creativity. Surrounded by a lush garden and a field of wheat, she is the energy of growth, comfort, and natural plenty.', 3, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('emperor', 'The Emperor', 'Major Arcana', 'cards/emperor.jpg', 'Structure, authority, and discipline. Seated on his stone throne, he provides stability and order — the framework that turns chaos into something lasting.', 4, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('hierophant', 'The Hierophant', 'Major Arcana', 'cards/hierophant.jpg', 'Tradition, spiritual guidance, and shared wisdom. He is the bridge between the sacred and the everyday, offering teachings passed down through generations.', 5, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('lovers', 'The Lovers', 'Major Arcana', 'cards/lovers.jpg', 'Love, harmony, and a meaningful choice. More than romance, this card speaks of alignment — a decision made with the whole heart.', 6, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('chariot', 'The Chariot', 'Major Arcana', 'cards/chariot.jpg', 'Determination, willpower, and victory through focus. Two sphinxes pull in different directions, yet the charioteer keeps them both moving forward.', 7, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('strength', 'Strength', 'Major Arcana', 'cards/strength.jpg', 'Courage, patience, and gentle mastery over instinct. The woman calmly closes the lion''s jaws, showing that true power comes from compassion, not force.', 8, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('hermit', 'The Hermit', 'Major Arcana', 'cards/hermit.jpg', 'Solitude, introspection, and inner guidance. With his lantern raised high, he lights the way for anyone willing to look within for answers.', 9, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('wheel-of-fortune', 'Wheel of Fortune', 'Major Arcana', 'cards/wheel-of-fortune.jpg', 'Cycles, fate, and turning points. The wheel never stops spinning — what rises must fall — bringing change beyond your control but not beyond your understanding.', 10, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('justice', 'Justice', 'Major Arcana', 'cards/justice.jpg', 'Fairness, truth, and consequence. With her scales and her sword, she reminds you that every choice carries a weight and every action has an answer.', 11, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('hanged-man', 'The Hanged Man', 'Major Arcana', 'cards/hanged-man.jpg', 'Surrender, new perspective, and letting go. Suspended upside down, he sees the world differently — sometimes you must pause in order to gain clarity.', 12, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('death', 'Death', 'Major Arcana', 'cards/death.jpg', 'Transformation, endings, and rebirth. Not a literal death, but the necessary ending that clears the ground for something new to begin.', 13, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('temperance', 'Temperance', 'Major Arcana', 'cards/temperance.jpg', 'Balance, moderation, and patient blending. The angel pours water between two cups, showing that harmony comes from mixing opposites in the right measure.', 14, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('devil', 'The Devil', 'Major Arcana', 'cards/devil.jpg', 'Bondage, materialism, and the shadow self. Chained to the pedestal, the figures could leave at any moment — the card asks what truly holds you back.', 15, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('tower', 'The Tower', 'Major Arcana', 'cards/tower.jpg', 'Sudden upheaval and revelation. Struck by lightning, the tower crumbles — false structures fall away and truth remains in the ashes.', 16, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('star', 'The Star', 'Major Arcana', 'cards/star.jpg', 'Hope, inspiration, and healing. Kneeling by the water, the figure pours life back into the world — a gentle promise that renewal follows hardship.', 17, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('moon', 'The Moon', 'Major Arcana', 'cards/moon.jpg', 'Illusion, fear, and the subconscious. The moon lights the path but distorts it — not everything in the dark is what it seems; trust your intuition.', 18, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('sun', 'The Sun', 'Major Arcana', 'cards/sun.jpg', 'Joy, success, and vitality. The sun shines over a walled garden where a child rides a white horse — pure, uncomplicated happiness.', 19, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('judgement', 'Judgement', 'Major Arcana', 'cards/judgement.jpg', 'Rebirth, inner calling, and absolution. The angel''s trumpet wakes the figures from their graves — a call to rise, answer, and begin again.', 20, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('world', 'The World', 'Major Arcana', 'cards/world.jpg', 'Completion, integration, and wholeness. Dancing inside a laurel wreath, the figure has finished the great journey — achievement and the close of a cycle.', 21, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('wands-ace', 'Ace of Wands', 'Wands', 'cards/wands-ace.jpg', 'A spark of inspiration and raw creative potential. A hand emerges from the clouds holding a sprouting wand — the seed of a bold new venture.', 22, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('wands-02', 'Two of Wands', 'Wands', 'cards/wands-02.jpg', 'Planning, decision, and looking toward the horizon. Standing on a castle battlement with a globe in hand, you weigh the world — the choice of where to go next is yours.', 23, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('wands-03', 'Three of Wands', 'Wands', 'cards/wands-03.jpg', 'Expansion, foresight, and early success. Ships sail on the horizon while the merchant watches from the shore — your groundwork is beginning to pay off.', 24, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('wands-04', 'Four of Wands', 'Wands', 'cards/wands-04.jpg', 'Celebration, harmony, and a milestone reached. A garlanded pavilion marks a happy occasion — homecoming, reunion, or a well-earned rest.', 25, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('wands-05', 'Five of Wands', 'Wands', 'cards/wands-05.jpg', 'Conflict, competition, and clashing egos. Five figures swing their wands in a mock battle — disagreement tests you, but it need not defeat you.', 26, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('wands-06', 'Six of Wands', 'Wands', 'cards/wands-06.jpg', 'Victory, recognition, and public success. Carried on shoulders through cheering crowds, the rider shows that effort is seen and rewarded.', 27, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('wands-07', 'Seven of Wands', 'Wands', 'cards/wands-07.jpg', 'Defense, perseverance, and protecting your ground. From the hilltop you fend off attackers from above — you hold the advantage, so stand firm.', 28, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('wands-08', 'Eight of Wands', 'Wands', 'cards/wands-08.jpg', 'Speed, swift action, and rapid movement. Eight wands fly through the air like arrows — a message, project, or change arriving faster than expected.', 29, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('wands-09', 'Nine of Wands', 'Wands', 'cards/wands-09.jpg', 'Resilience, grit, and the last stand. Wounded but watchful, you lean on your wand — tired, perhaps, but nearly there. Keep going.', 30, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('wands-10', 'Ten of Wands', 'Wands', 'cards/wands-10.jpg', 'Burden, responsibility, and overwhelm. Carrying all ten wands at once, you struggle forward — success can become a weight when you carry it alone.', 31, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('wands-page', 'Page of Wands', 'Wands', 'cards/wands-page.jpg', 'Curiosity, exploration, and a burst of creative energy. The page gazes at his wand like a messenger bearing exciting news — a new passion to pursue.', 32, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('wands-knight', 'Knight of Wands', 'Wands', 'cards/wands-knight.jpg', 'Impulsiveness, adventure, and charging ahead. The knight rides off in search of quests — bold, passionate action, sometimes without a plan.', 33, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('wands-queen', 'Queen of Wands', 'Wands', 'cards/wands-queen.jpg', 'Confidence, warmth, and independent determination. Seated with her wand, she is fire made steady — a charismatic presence who inspires everyone around her.', 34, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('wands-king', 'King of Wands', 'Wands', 'cards/wands-king.jpg', 'Vision, leadership, and mastery of fire. The king holds his wand like a scepter — bold ideas executed with the authority of hard-won experience.', 35, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('cups-ace', 'Ace of Cups', 'Cups', 'cards/cups-ace.jpg', 'An overflowing cup of new love, joy, and emotional beginnings. A hand from the clouds offers a vessel brimming with feeling — a fresh start of the heart.', 36, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('cups-02', 'Two of Cups', 'Cups', 'cards/cups-02.jpg', 'Partnership, mutual attraction, and union. Two figures exchange cups face to face — a meaningful connection built on equality and affection.', 37, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('cups-03', 'Three of Cups', 'Cups', 'cards/cups-03.jpg', 'Friendship, community, and shared celebration. Three women raise their cups in a joyful gathering — togetherness and collective happiness.', 38, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('cups-04', 'Four of Cups', 'Cups', 'cards/cups-04.jpg', 'Apathy, contemplation, and a missed opportunity. Seated under a tree, the figure ignores the cup offered from a cloud — sometimes you must look up to see what is being given.', 39, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('cups-05', 'Five of Cups', 'Cups', 'cards/cups-05.jpg', 'Loss, grief, and dwelling on what is gone. Kneeling before three spilled cups, the figure mourns — but two cups still stand behind him. Not all is lost.', 40, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('cups-06', 'Six of Cups', 'Cups', 'cards/cups-06.jpg', 'Nostalgia, childhood memory, and innocent joy. Children fill their cups in a garden — a return to simpler times and pure, uncomplicated happiness.', 41, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('cups-07', 'Seven of Cups', 'Cups', 'cards/cups-07.jpg', 'Choices, fantasy, and wishful thinking. Seven cups drift in the clouds, each holding a vision — dreams are abundant, but only one can become real.', 42, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('cups-08', 'Eight of Cups', 'Cups', 'cards/cups-08.jpg', 'Walking away, deeper meaning, and leaving the familiar. The figure departs at night with six cups behind — sometimes growth means leaving what is comfortable.', 43, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('cups-09', 'Nine of Cups', 'Cups', 'cards/cups-09.jpg', 'Contentment, satisfaction, and a wish fulfilled. Arms crossed before nine full cups, the figure savours the quiet joy of having enough.', 44, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('cups-10', 'Ten of Cups', 'Cups', 'cards/cups-10.jpg', 'Lasting harmony, love, and emotional fulfillment. A rainbow arcs over a family dancing together — deep belonging and a happy home.', 45, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('cups-page', 'Page of Cups', 'Cups', 'cards/cups-page.jpg', 'Creativity, intuition, and a gentle new message. The page gazes at the fish in his cup — a sensitive soul receiving emotional or artistic inspiration.', 46, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('cups-knight', 'Knight of Cups', 'Cups', 'cards/cups-knight.jpg', 'Romance, charm, and following the heart. The knight rides a white horse bearing a cup — an offer of love, or a creative pursuit chased with idealism.', 47, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('cups-queen', 'Queen of Cups', 'Cups', 'cards/cups-queen.jpg', 'Compassion, emotional maturity, and deep intuition. Seated by the sea with her cup, she is a nurturing, empathic presence who feels more than she says.', 48, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('cups-king', 'King of Cups', 'Cups', 'cards/cups-king.jpg', 'Emotional balance, diplomacy, and mastery of feelings. Ruling the waves from his throne, he is calm control over deep waters — generous, wise, and kind.', 49, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('swords-ace', 'Ace of Swords', 'Swords', 'cards/swords-ace.jpg', 'A breakthrough of clarity and a piercing new idea. The hand from the clouds raises a sword crowned with laurels — the triumph of the mind.', 50, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('swords-02', 'Two of Swords', 'Swords', 'cards/swords-02.jpg', 'Indecision, difficult choices, and stalemate. Blindfolded and balancing two crossed blades, the figure shows that the hardest choice is often the one you avoid.', 51, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('swords-03', 'Three of Swords', 'Swords', 'cards/swords-03.jpg', 'Heartbreak, sorrow, and painful truth. A storm rages over a heart pierced by three swords — grief that is real, but not forever.', 52, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('swords-04', 'Four of Swords', 'Swords', 'cards/swords-04.jpg', 'Rest, recovery, and quiet contemplation. The figure lies in peaceful repose — a necessary pause that restores your strength.', 53, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('swords-05', 'Five of Swords', 'Swords', 'cards/swords-05.jpg', 'Conflict, hollow victory, and winning at a cost. The victor gathers swords while others retreat — a win that can leave you poorer than before.', 54, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('swords-06', 'Six of Swords', 'Swords', 'cards/swords-06.jpg', 'Transition, moving on, and leaving turmoil behind. A ferryman carries passengers toward calm waters — a journey toward healing and a gentler shore.', 55, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('swords-07', 'Seven of Swords', 'Swords', 'cards/swords-07.jpg', 'Strategy, deception, and slipping away. The figure creeps off with five swords, leaving two behind — sometimes you must act quietly to get what you need.', 56, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('swords-08', 'Eight of Swords', 'Swords', 'cards/swords-08.jpg', 'Restriction, negative thoughts, and feeling trapped. Bound and blindfolded before eight swords, the figure reminds you that the cage is often one you build yourself.', 57, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('swords-09', 'Nine of Swords', 'Swords', 'cards/swords-09.jpg', 'Anxiety, worry, and sleepless nights. Sitting up in bed with nine swords on the wall, the figure shows how fear looms largest in the dark.', 58, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('swords-10', 'Ten of Swords', 'Swords', 'cards/swords-10.jpg', 'Painful endings, deep wounds, and rock bottom. Pierced by ten swords at dawn — the darkest moment right before the light returns.', 59, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('swords-page', 'Page of Swords', 'Swords', 'cards/swords-page.jpg', 'Vigilance, curiosity, and a sharp new idea. The page raises his sword — an eager mind hunting for truth and fresh perspectives.', 60, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('swords-knight', 'Knight of Swords', 'Swords', 'cards/swords-knight.jpg', 'Ambition, action, and charging into battle. The knight gallops with his sword raised — swift and decisive, and sometimes reckless.', 61, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('swords-queen', 'Queen of Swords', 'Swords', 'cards/swords-queen.jpg', 'Independence, clear boundaries, and honest intellect. Seated among the clouds with her sword, she is uncompromising truth — perceptive, fair, and direct.', 62, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('swords-king', 'King of Swords', 'Swords', 'cards/swords-king.jpg', 'Authority, truth, and intellectual power. The king lifts his sword to the sky — reason and justice wielded with a steady, incorruptible hand.', 63, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('pentacles-ace', 'Ace of Pentacles', 'Pentacles', 'cards/pentacles-ace.jpg', 'A new financial opportunity and a material beginning. The hand from the cloud offers a golden pentacle — prosperity and security taking root.', 64, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('pentacles-02', 'Two of Pentacles', 'Pentacles', 'cards/pentacles-02.jpg', 'Balance, adaptability, and juggling priorities. The figure dances with two pentacles linked by an infinity ribbon — keeping many things in motion at once.', 65, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('pentacles-03', 'Three of Pentacles', 'Pentacles', 'cards/pentacles-03.jpg', 'Teamwork, craftsmanship, and collaboration. The mason carves a cathedral arch while his client looks on — skill recognized and rewarded through cooperation.', 66, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('pentacles-04', 'Four of Pentacles', 'Pentacles', 'cards/pentacles-04.jpg', 'Security, control, and holding on tightly. Pentacles clutched to crown, hands, and feet give stability — but at the cost of openness.', 67, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('pentacles-05', 'Five of Pentacles', 'Pentacles', 'cards/pentacles-05.jpg', 'Hardship, loss, and feeling left out in the cold. Two figures pass a lit window in the snow — struggle is real, but shelter and help exist if you ask for them.', 68, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('pentacles-06', 'Six of Pentacles', 'Pentacles', 'cards/pentacles-06.jpg', 'Generosity, giving, and fair exchange. The merchant weighs coins on his scales, giving to those in need — charity and balanced reciprocity.', 69, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('pentacles-07', 'Seven of Pentacles', 'Pentacles', 'cards/pentacles-07.jpg', 'Patience, long-term view, and assessing progress. The farmer leans on his staff, surveying vines heavy with fruit — hard work is growing, but the harvest is not yet in.', 70, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('pentacles-08', 'Eight of Pentacles', 'Pentacles', 'cards/pentacles-08.jpg', 'Apprenticeship, skill, and diligent practice. The artisan carves pentacles one by one — mastery comes from focused, repeated effort.', 71, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('pentacles-09', 'Nine of Pentacles', 'Pentacles', 'cards/pentacles-09.jpg', 'Luxury, self-sufficiency, and enjoying the fruits of labor. The woman walks her vineyard with a hooded falcon — independence and refined comfort.', 72, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('pentacles-10', 'Ten of Pentacles', 'Pentacles', 'cards/pentacles-10.jpg', 'Wealth, inheritance, and lasting legacy. A family beneath an archway of pentacles — prosperity shared across generations.', 73, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('pentacles-page', 'Page of Pentacles', 'Pentacles', 'cards/pentacles-page.jpg', 'Ambition, practicality, and a new opportunity. The page studies his pentacle — a grounded approach to manifesting material goals.', 74, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('pentacles-knight', 'Knight of Pentacles', 'Pentacles', 'cards/pentacles-knight.jpg', 'Hard work, routine, and dependable progress. The knight rides slowly across fertile fields — steady, methodical effort that reliably gets results.', 75, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('pentacles-queen', 'Queen of Pentacles', 'Pentacles', 'cards/pentacles-queen.jpg', 'Nurturing, practicality, and abundant comfort. Seated in her lush garden, she is a generous provider of material and emotional security.', 76, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('pentacles-king', 'King of Pentacles', 'Pentacles', 'cards/pentacles-king.jpg', 'Success, abundance, and material mastery. The king on his throne, the bull''s head on his pedestal — wealth and business acumen at their peak.', 77, strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));
INSERT INTO TarotCardTranslations (cardId, language, title, arcana, description) VALUES
  ('fool', 'en', 'The Fool', 'Major Arcana', 'A leap of faith into the unknown. The Fool stands at the edge of a cliff with only a small bag and a dog at his heels, ready to begin a journey full of possibility and innocent trust.'),
  ('fool', 'fi', 'Narri', 'Iso arkana', 'Uskon hyppy tuntemattomaan. Narri seisoo jyrkänteen reunalla mukanaan vain pieni kukkaro ja uskollinen koira, valmiina aloittamaan matkan, joka on täynnä mahdollisuuksia ja vilpitöntä luottamusta.'),
  ('magician', 'en', 'The Magician', 'Major Arcana', 'Manifestation and resourcefulness. With one hand raised to heaven and one pointing to earth, the Magician shows you already hold every tool needed to turn an idea into reality.'),
  ('magician', 'fi', 'Maagikko', 'Iso arkana', 'Manifestaatio ja neuvokkuus. Toinen käsi taivasta kohti ja toinen maata kohti osoittavat, että sinulla on jo kaikki tarvittavat välineet muuttaaksesi idean todellisuudeksi.'),
  ('high-priestess', 'en', 'The High Priestess', 'Major Arcana', 'Intuition, mystery, and inner knowledge. Seated between the black and white pillars, she guards the secrets that surface when you trust your instincts over what is obvious.'),
  ('high-priestess', 'fi', 'Ylipapitar', 'Iso arkana', 'Intuitio, mysteeri ja sisäinen tieto. Mustien ja valkoisten pylväiden välissä istuva Ylipapitar vartioi salaisuuksia, jotka tulevat esiin, kun luotat vaistoosi selvän sijaan.'),
  ('empress', 'en', 'The Empress', 'Major Arcana', 'Abundance, fertility, and nurturing creativity. Surrounded by a lush garden and a field of wheat, she is the energy of growth, comfort, and natural plenty.'),
  ('empress', 'fi', 'Hallitsijatar', 'Iso arkana', 'Runsaus, hedelmällisyys ja hoivaava luovuus. Rehevän puutarhan ja viljapellon ympäröimänä hän on kasvun, mukavuuden ja luonnollisen runsauden energiaa.'),
  ('emperor', 'en', 'The Emperor', 'Major Arcana', 'Structure, authority, and discipline. Seated on his stone throne, he provides stability and order — the framework that turns chaos into something lasting.'),
  ('emperor', 'fi', 'Hallitsija', 'Iso arkana', 'Rakenne, auktoriteetti ja kuri. Kivisellä valtaistuimellaan istuva Hallitsija luo vakautta ja järjestystä — kehikon, joka muuttaa kaaoksen kestäväksi.'),
  ('hierophant', 'en', 'The Hierophant', 'Major Arcana', 'Tradition, spiritual guidance, and shared wisdom. He is the bridge between the sacred and the everyday, offering teachings passed down through generations.'),
  ('hierophant', 'fi', 'Ylipappi', 'Iso arkana', 'Perinne, henkinen opastus ja jaettu viisaus. Hän on sillanrakentaja pyhän ja arkisen välillä ja tarjoaa sukupolvelta toiselle välittyviä opetuksia.'),
  ('lovers', 'en', 'The Lovers', 'Major Arcana', 'Love, harmony, and a meaningful choice. More than romance, this card speaks of alignment — a decision made with the whole heart.'),
  ('lovers', 'fi', 'Rakastavaiset', 'Iso arkana', 'Rakkaus, harmonia ja merkityksellinen valinta. Enemmän kuin romanssi, tämä kortti puhuu yhteensopivuudesta — päätöksestä, joka tehdään koko sydämellä.'),
  ('chariot', 'en', 'The Chariot', 'Major Arcana', 'Determination, willpower, and victory through focus. Two sphinxes pull in different directions, yet the charioteer keeps them both moving forward.'),
  ('chariot', 'fi', 'Vaunut', 'Iso arkana', 'Päättäväisyys, tahdonvoima ja voitto keskittymisen kautta. Kaksi sfinksiä vetää eri suuntiin, mutta vaununajaja pitää molemmat liikkeessä samaan suuntaan.'),
  ('strength', 'en', 'Strength', 'Major Arcana', 'Courage, patience, and gentle mastery over instinct. The woman calmly closes the lion''s jaws, showing that true power comes from compassion, not force.'),
  ('strength', 'fi', 'Voima', 'Iso arkana', 'Rohkeus, kärsivällisyys ja vaiston lempeä hallinta. Nainen sulkee leijonan leuat rauhallisesti, näyttäen, että todellinen voima tulee myötätunnosta, ei väkivallasta.'),
  ('hermit', 'en', 'The Hermit', 'Major Arcana', 'Solitude, introspection, and inner guidance. With his lantern raised high, he lights the way for anyone willing to look within for answers.'),
  ('hermit', 'fi', 'Erakko', 'Iso arkana', 'Yksinäisyys, itsetutkiskelu ja sisäinen opastus. Lyhty korkealla kohotettuna hän valaisee tien kaikille, jotka ovat valmiita etsimään vastauksia sisältään.'),
  ('wheel-of-fortune', 'en', 'Wheel of Fortune', 'Major Arcana', 'Cycles, fate, and turning points. The wheel never stops spinning — what rises must fall — bringing change beyond your control but not beyond your understanding.'),
  ('wheel-of-fortune', 'fi', 'Kohtalonpyörä', 'Iso arkana', 'Syklit, kohtalo ja käännekohdat. Pyörä ei pysähdy koskaan — mikä nousee, myös laskee — tuoden muutoksen, joka on hallitsemattomasi mutta ei ymmärryksesi ulkopuolella.'),
  ('justice', 'en', 'Justice', 'Major Arcana', 'Fairness, truth, and consequence. With her scales and her sword, she reminds you that every choice carries a weight and every action has an answer.'),
  ('justice', 'fi', 'Oikeudenmukaisuus', 'Iso arkana', 'Oikeudenmukaisuus, totuus ja seuraamus. Vaaka ja miekka muistuttavat, että jokaisella valinnalla on painonsa ja jokaisella teolla vastauksensa.'),
  ('hanged-man', 'en', 'The Hanged Man', 'Major Arcana', 'Surrender, new perspective, and letting go. Suspended upside down, he sees the world differently — sometimes you must pause in order to gain clarity.'),
  ('hanged-man', 'fi', 'Hirtetty', 'Iso arkana', 'Antautuminen, uusi näkökulma ja irti päästäminen. Ylösalaisin roikkuessaan hän näkee maailman toisin — joskus täytyy pysähtyä saadakseen selkeyttä.'),
  ('death', 'en', 'Death', 'Major Arcana', 'Transformation, endings, and rebirth. Not a literal death, but the necessary ending that clears the ground for something new to begin.'),
  ('death', 'fi', 'Kuolema', 'Iso arkana', 'Muutos, päätökset ja uudelleensyntyminen. Ei kirjaimellinen kuolema, vaan välttämätön loppu, joka raivaa tilaa uudelle alulle.'),
  ('temperance', 'en', 'Temperance', 'Major Arcana', 'Balance, moderation, and patient blending. The angel pours water between two cups, showing that harmony comes from mixing opposites in the right measure.'),
  ('temperance', 'fi', 'Kohtuus', 'Iso arkana', 'Tasapaino, maltillisuus ja kärsivällinen sekoittaminen. Enkeli kaataa vettä kahden kupin välillä, näyttäen, että harmonia syntyy, kun vastakohtia sekoittaa oikeassa suhteessa.'),
  ('devil', 'en', 'The Devil', 'Major Arcana', 'Bondage, materialism, and the shadow self. Chained to the pedestal, the figures could leave at any moment — the card asks what truly holds you back.'),
  ('devil', 'fi', 'Paholainen', 'Iso arkana', 'Sitoutuneisuus, materialismi ja varjominä. Jalustaan kahlitut hahmot voisivat lähteä milloin tahansa — kortti kysyy, mikä todella pitää sinut kahleissa.'),
  ('tower', 'en', 'The Tower', 'Major Arcana', 'Sudden upheaval and revelation. Struck by lightning, the tower crumbles — false structures fall away and truth remains in the ashes.'),
  ('tower', 'fi', 'Torni', 'Iso arkana', 'Äkillinen mullistus ja paljastus. Salaman iskemä torni sortuu — valheelliset rakenteet kaatuvat ja totuus jää jäljelle tuhkaan.'),
  ('star', 'en', 'The Star', 'Major Arcana', 'Hope, inspiration, and healing. Kneeling by the water, the figure pours life back into the world — a gentle promise that renewal follows hardship.'),
  ('star', 'fi', 'Tähti', 'Iso arkana', 'Toivo, inspiraatio ja parantuminen. Veden äärellä polvillaan oleva hahmo kaataa elämää takaisin maailmaan — lempeä lupaus siitä, että vaikeuden jälkeen tulee uudistuminen.'),
  ('moon', 'en', 'The Moon', 'Major Arcana', 'Illusion, fear, and the subconscious. The moon lights the path but distorts it — not everything in the dark is what it seems; trust your intuition.'),
  ('moon', 'fi', 'Kuu', 'Iso arkana', 'Harha, pelko ja alitajunta. Kuu valaisee polun mutta vääristää sen — kaikki pimeässä ei ole sitä miltä näyttää; luota intuitioosi.'),
  ('sun', 'en', 'The Sun', 'Major Arcana', 'Joy, success, and vitality. The sun shines over a walled garden where a child rides a white horse — pure, uncomplicated happiness.'),
  ('sun', 'fi', 'Aurinko', 'Iso arkana', 'Ilo, menestys ja elinvoima. Aurinko paistaa muurien ympäröimään puutarhaan, jossa lapsi ratsastaa valkoisella hevosella — puhdasta, mutkatonta onnea.'),
  ('judgement', 'en', 'Judgement', 'Major Arcana', 'Rebirth, inner calling, and absolution. The angel''s trumpet wakes the figures from their graves — a call to rise, answer, and begin again.'),
  ('judgement', 'fi', 'Tuomio', 'Iso arkana', 'Uudelleensyntyminen, sisäinen kutsu ja vapautus. Enkelin torvi herättää hahmot haudoistaan — kutsu nousta, vastata ja aloittaa alusta.'),
  ('world', 'en', 'The World', 'Major Arcana', 'Completion, integration, and wholeness. Dancing inside a laurel wreath, the figure has finished the great journey — achievement and the close of a cycle.'),
  ('world', 'fi', 'Maailmankaikkeus', 'Iso arkana', 'Kokonaisuus, integraatio ja täyttymys. Laakeriseppeleen sisällä tanssiva hahmo on päättänyt suuren matkan — saavutus ja syklin päättyminen.'),
  ('wands-ace', 'en', 'Ace of Wands', 'Wands', 'A spark of inspiration and raw creative potential. A hand emerges from the clouds holding a sprouting wand — the seed of a bold new venture.'),
  ('wands-ace', 'fi', 'Sauvojen ässä', 'Sauvat', 'Inspiraation kipinä ja raaka luova potentiaali. Pilvestä nouseva käsi kannattelee itävää sauvaa — rohkean uuden hankkeen siemen.'),
  ('wands-02', 'en', 'Two of Wands', 'Wands', 'Planning, decision, and looking toward the horizon. Standing on a castle battlement with a globe in hand, you weigh the world — the choice of where to go next is yours.'),
  ('wands-02', 'fi', 'Sauvojen kaksi', 'Sauvat', 'Suunnittelu, päätös ja katse kohti horisonttia. Linnan muurilla seisova, karttapalloa käsissään pitävä hahmo punnitsee maailmaa — seuraava valinta on sinun.'),
  ('wands-03', 'en', 'Three of Wands', 'Wands', 'Expansion, foresight, and early success. Ships sail on the horizon while the merchant watches from the shore — your groundwork is beginning to pay off.'),
  ('wands-03', 'fi', 'Sauvojen kolme', 'Sauvat', 'Laajeneminen, kaukonäköisyys ja varhainen menestys. Laivat purjehtivat horisontissa, kun kauppias tarkkailee rannalta — pohjatyösi alkaa jo tuottaa hedelmää.'),
  ('wands-04', 'en', 'Four of Wands', 'Wands', 'Celebration, harmony, and a milestone reached. A garlanded pavilion marks a happy occasion — homecoming, reunion, or a well-earned rest.'),
  ('wands-04', 'fi', 'Sauvojen neljä', 'Sauvat', 'Juhla, harmonia ja saavutettu välietappi. Kukkaseppeleillä koristeltu paviljonki merkitsee iloista tilaisuutta — kotiinpaluuta, tapaamista tai ansaittua lepoa.'),
  ('wands-05', 'en', 'Five of Wands', 'Wands', 'Conflict, competition, and clashing egos. Five figures swing their wands in a mock battle — disagreement tests you, but it need not defeat you.'),
  ('wands-05', 'fi', 'Sauvojen viisi', 'Sauvat', 'Konflikti, kilpailu ja egojen törmääminen. Viisi hahmoa heiluttaa sauvojaan näytöstaistelussa — erimielisyys koettelee sinua, mutta sen ei tarvitse voittaa sinua.'),
  ('wands-06', 'en', 'Six of Wands', 'Wands', 'Victory, recognition, and public success. Carried on shoulders through cheering crowds, the rider shows that effort is seen and rewarded.'),
  ('wands-06', 'fi', 'Sauvojen kuusi', 'Sauvat', 'Voitto, tunnustus ja julkinen menestys. Kansan kannattelemana ratsastaja näyttää, että vaiva näkyy ja palkitaan.'),
  ('wands-07', 'en', 'Seven of Wands', 'Wands', 'Defense, perseverance, and protecting your ground. From the hilltop you fend off attackers from above — you hold the advantage, so stand firm.'),
  ('wands-07', 'fi', 'Sauvojen seitsemän', 'Sauvat', 'Puolustus, sitkeys ja asemien pitäminen. Kukkulalta käsin torjut hyökkääjiä ylhäältä — sinulla on etulyöntiasema, joten seiso lujasti.'),
  ('wands-08', 'en', 'Eight of Wands', 'Wands', 'Speed, swift action, and rapid movement. Eight wands fly through the air like arrows — a message, project, or change arriving faster than expected.'),
  ('wands-08', 'fi', 'Sauvojen kahdeksan', 'Sauvat', 'Nopeus, nopea toiminta ja vauhdikas liike. Kahdeksan sauvaa lentää ilman halki kuin nuolet — viesti, projekti tai muutos saapuu odotettua nopeammin.'),
  ('wands-09', 'en', 'Nine of Wands', 'Wands', 'Resilience, grit, and the last stand. Wounded but watchful, you lean on your wand — tired, perhaps, but nearly there. Keep going.'),
  ('wands-09', 'fi', 'Sauvojen yhdeksän', 'Sauvat', 'Kestävyys, sisu ja viimeinen taistelu. Haavoittunut mutta valpas, nojaat sauvaasi — väsynyt ehkä, mutta melkein perillä. Jatka.'),
  ('wands-10', 'en', 'Ten of Wands', 'Wands', 'Burden, responsibility, and overwhelm. Carrying all ten wands at once, you struggle forward — success can become a weight when you carry it alone.'),
  ('wands-10', 'fi', 'Sauvojen kymmenen', 'Sauvat', 'Vastuu, kuorma ja ylikuormitus. Kannat kaikkia kymmentä sauvaa kerralla ja kampeat eteenpäin — menestys voi muuttua taakaksi, kun kannat sen yksin.'),
  ('wands-page', 'en', 'Page of Wands', 'Wands', 'Curiosity, exploration, and a burst of creative energy. The page gazes at his wand like a messenger bearing exciting news — a new passion to pursue.'),
  ('wands-page', 'fi', 'Sauvojen lähetti', 'Sauvat', 'Uteliaisuus, tutkiminen ja luovan energian purkaus. Lähetti tuijottaa sauvaansa kuin viestintuoja, joka tuo jännittävän uutisen — uusi intohimo, jota seurata.'),
  ('wands-knight', 'en', 'Knight of Wands', 'Wands', 'Impulsiveness, adventure, and charging ahead. The knight rides off in search of quests — bold, passionate action, sometimes without a plan.'),
  ('wands-knight', 'fi', 'Sauvojen ritari', 'Sauvat', 'Impulsiivisuus, seikkailu ja rynnäkkö eteenpäin. Ritari ratsastaa etsimään seikkailuja — rohkeaa, intohimoista toimintaa, joskus ilman suunnitelmaa.'),
  ('wands-queen', 'en', 'Queen of Wands', 'Wands', 'Confidence, warmth, and independent determination. Seated with her wand, she is fire made steady — a charismatic presence who inspires everyone around her.'),
  ('wands-queen', 'fi', 'Sauvojen kuningatar', 'Sauvat', 'Itseluottamus, lämpö ja itsenäinen päättäväisyys. Sauva sylissään istuva Kuningatar on liekki, joka on muuttunut vakituiseksi — karismaattinen läsnäolo, joka inspiroi kaikkia ympärillään.'),
  ('wands-king', 'en', 'King of Wands', 'Wands', 'Vision, leadership, and mastery of fire. The king holds his wand like a scepter — bold ideas executed with the authority of hard-won experience.'),
  ('wands-king', 'fi', 'Sauvojen kuningas', 'Sauvat', 'Visio, johtajuus ja tulen hallinta. Kuningas pitää sauvaansa kuin valtikkaa — rohkeat ideat toteutetaan kokemuksen tuomalla auktoriteetilla.'),
  ('cups-ace', 'en', 'Ace of Cups', 'Cups', 'An overflowing cup of new love, joy, and emotional beginnings. A hand from the clouds offers a vessel brimming with feeling — a fresh start of the heart.'),
  ('cups-ace', 'fi', 'Maljojen ässä', 'Maljat', 'Ylivuotava malja, joka merkitsee uutta rakkautta, iloa ja emotionaalisia alkua. Pilvestä ojentuva käsi tarjoaa täyteen valuvaa astiaa — sydämen uusi alku.'),
  ('cups-02', 'en', 'Two of Cups', 'Cups', 'Partnership, mutual attraction, and union. Two figures exchange cups face to face — a meaningful connection built on equality and affection.'),
  ('cups-02', 'fi', 'Maljojen kaksi', 'Maljat', 'Kumppanuus, molemminpuolinen kiintymys ja liitto. Kaksi hahmoa vaihtaa maljoja kasvotusten — merkityksellinen yhteys, joka rakentuu tasa-arvolle ja hellyydelle.'),
  ('cups-03', 'en', 'Three of Cups', 'Cups', 'Friendship, community, and shared celebration. Three women raise their cups in a joyful gathering — togetherness and collective happiness.'),
  ('cups-03', 'fi', 'Maljojen kolme', 'Maljat', 'Ystävyys, yhteisö ja jaettu juhla. Kolme naista kohottaa maljansa iloisessa kokoontumisessa — yhdessäolo ja yhteinen ilo.'),
  ('cups-04', 'en', 'Four of Cups', 'Cups', 'Apathy, contemplation, and a missed opportunity. Seated under a tree, the figure ignores the cup offered from a cloud — sometimes you must look up to see what is being given.'),
  ('cups-04', 'fi', 'Maljojen neljä', 'Maljat', 'Apatia, pohdiskelu ja menetetty tilaisuus. Puun alla istuva hahmo ei huomaa pilvestä ojennettua maljaa — joskus täytyy katsoa ylös nähdäkseen, mitä tarjotaan.'),
  ('cups-05', 'en', 'Five of Cups', 'Cups', 'Loss, grief, and dwelling on what is gone. Kneeling before three spilled cups, the figure mourns — but two cups still stand behind him. Not all is lost.'),
  ('cups-05', 'fi', 'Maljojen viisi', 'Maljat', 'Menetys, suru ja kadonneen sureminen. Polvillaan kolmen kaatuneen maljan edessä hahmo suree — mutta kaksi maljaa seisoo vielä hänen takanaan. Kaikki ei ole mennyttä.'),
  ('cups-06', 'en', 'Six of Cups', 'Cups', 'Nostalgia, childhood memory, and innocent joy. Children fill their cups in a garden — a return to simpler times and pure, uncomplicated happiness.'),
  ('cups-06', 'fi', 'Maljojen kuusi', 'Maljat', 'Nostalgia, lapsuusmuistot ja viaton ilo. Lapset täyttävät maljansa puutarhassa — paluu yksinkertaisempiin aikoihin ja puhtaaseen, mutkattomaan onneen.'),
  ('cups-07', 'en', 'Seven of Cups', 'Cups', 'Choices, fantasy, and wishful thinking. Seven cups drift in the clouds, each holding a vision — dreams are abundant, but only one can become real.'),
  ('cups-07', 'fi', 'Maljojen seitsemän', 'Maljat', 'Valinnat, fantasia ja toiveajattelu. Seitsemän maljaa leijuu pilvissä, kukin pitäen sisällään vision — unelmia on runsaasti, mutta vain yksi voi toteutua.'),
  ('cups-08', 'en', 'Eight of Cups', 'Cups', 'Walking away, deeper meaning, and leaving the familiar. The figure departs at night with six cups behind — sometimes growth means leaving what is comfortable.'),
  ('cups-08', 'fi', 'Maljojen kahdeksan', 'Maljat', 'Poislähteminen, syvempi merkitys ja tutun jättäminen. Hahmo lähtee yöllä kuusi maljaa jäljelle jättäen — joskus kasvu tarkoittaa mukavuuden jättämistä.'),
  ('cups-09', 'en', 'Nine of Cups', 'Cups', 'Contentment, satisfaction, and a wish fulfilled. Arms crossed before nine full cups, the figure savours the quiet joy of having enough.'),
  ('cups-09', 'fi', 'Maljojen yhdeksän', 'Maljat', 'Tyytyväisyys, täyttymys ja toteutunut toive. Kädet ristissä yhdeksän täyden maljan edessä hahmo nauttii riittämisen hiljaisesta ilosta.'),
  ('cups-10', 'en', 'Ten of Cups', 'Cups', 'Lasting harmony, love, and emotional fulfillment. A rainbow arcs over a family dancing together — deep belonging and a happy home.'),
  ('cups-10', 'fi', 'Maljojen kymmenen', 'Maljat', 'Kestävä harmonia, rakkaus ja emotionaalinen täyttymys. Sateenkaari kaartuu perheen yli, joka tanssii yhdessä — syvä yhteenkuuluvuus ja onnellinen koti.'),
  ('cups-page', 'en', 'Page of Cups', 'Cups', 'Creativity, intuition, and a gentle new message. The page gazes at the fish in his cup — a sensitive soul receiving emotional or artistic inspiration.'),
  ('cups-page', 'fi', 'Maljojen lähetti', 'Maljat', 'Luovuus, intuitio ja lempeä uusi viesti. Lähetti tuijottaa kalaa maljassaan — herkkä sielu, joka vastaanottaa emotionaalista tai taiteellista inspiraatiota.'),
  ('cups-knight', 'en', 'Knight of Cups', 'Cups', 'Romance, charm, and following the heart. The knight rides a white horse bearing a cup — an offer of love, or a creative pursuit chased with idealism.'),
  ('cups-knight', 'fi', 'Maljojen ritari', 'Maljat', 'Romanssi, viehätys ja sydämen seuraaminen. Ritari ratsastaa valkoisella hevosella mukanaan malja — rakkauden tarjous tai ihanteellisesti tavoiteltu luova päämäärä.'),
  ('cups-queen', 'en', 'Queen of Cups', 'Cups', 'Compassion, emotional maturity, and deep intuition. Seated by the sea with her cup, she is a nurturing, empathic presence who feels more than she says.'),
  ('cups-queen', 'fi', 'Maljojen kuningatar', 'Maljat', 'Myötätunto, emotionaalinen kypsyys ja syvä intuitio. Meren rannalla istuva, maljaansa pitävä Kuningatar on hoivaava, empaattinen läsnäolo, joka tuntee enemmän kuin sanoo.'),
  ('cups-king', 'en', 'King of Cups', 'Cups', 'Emotional balance, diplomacy, and mastery of feelings. Ruling the waves from his throne, he is calm control over deep waters — generous, wise, and kind.'),
  ('cups-king', 'fi', 'Maljojen kuningas', 'Maljat', 'Emotionaalinen tasapaino, diplomatia ja tunteiden hallinta. Aalloista käsin hallitseva Kuningas on rauhallinen kontrolli syvien vesien yli — antelias, viisas ja hyvä.'),
  ('swords-ace', 'en', 'Ace of Swords', 'Swords', 'A breakthrough of clarity and a piercing new idea. The hand from the clouds raises a sword crowned with laurels — the triumph of the mind.'),
  ('swords-ace', 'fi', 'Miekkojen ässä', 'Miekat', 'Selkeyden läpimurto ja lävistävä uusi idea. Pilvestä nouseva käsi kohottaa laakerilla kruunattua miekkaa — mielen voitto.'),
  ('swords-02', 'en', 'Two of Swords', 'Swords', 'Indecision, difficult choices, and stalemate. Blindfolded and balancing two crossed blades, the figure shows that the hardest choice is often the one you avoid.'),
  ('swords-02', 'fi', 'Miekkojen kaksi', 'Miekat', 'Päättämättömyys, vaikeat valinnat ja umpikuja. Side silmillä ja kaksi risteävää miekkaa tasapainottaen hahmo näyttää, että vaikein valinta on usein se, jota välttelet.'),
  ('swords-03', 'en', 'Three of Swords', 'Swords', 'Heartbreak, sorrow, and painful truth. A storm rages over a heart pierced by three swords — grief that is real, but not forever.'),
  ('swords-03', 'fi', 'Miekkojen kolme', 'Miekat', 'Sydänsuru, suru ja kivulias totuus. Myrsky riehuu kolmella miekalla lävistyneen sydämen yllä — suru, joka on todellinen, mutta ei ikuisesti.'),
  ('swords-04', 'en', 'Four of Swords', 'Swords', 'Rest, recovery, and quiet contemplation. The figure lies in peaceful repose — a necessary pause that restores your strength.'),
  ('swords-04', 'fi', 'Miekkojen neljä', 'Miekat', 'Lepo, toipuminen ja hiljainen pohdiskelu. Rauhallisesti lepäävä hahmo — välttämätön tauko, joka palauttaa voimasi.'),
  ('swords-05', 'en', 'Five of Swords', 'Swords', 'Conflict, hollow victory, and winning at a cost. The victor gathers swords while others retreat — a win that can leave you poorer than before.'),
  ('swords-05', 'fi', 'Miekkojen viisi', 'Miekat', 'Konflikti, ontto voitto ja voiton hinta. Voittaja kerää miekkoja samalla kun toiset vetäytyvät — voitto, joka voi jättää sinut köyhemmäksi kuin ennen.'),
  ('swords-06', 'en', 'Six of Swords', 'Swords', 'Transition, moving on, and leaving turmoil behind. A ferryman carries passengers toward calm waters — a journey toward healing and a gentler shore.'),
  ('swords-06', 'fi', 'Miekkojen kuusi', 'Miekat', 'Siirtymä, eteenpäin lähteminen ja myrskyn jättäminen taakse. Lautanmies kuljettaa matkustajia kohti tyynempiä vesiä — matka kohti paranemista ja lempeämpää rantaa.'),
  ('swords-07', 'en', 'Seven of Swords', 'Swords', 'Strategy, deception, and slipping away. The figure creeps off with five swords, leaving two behind — sometimes you must act quietly to get what you need.'),
  ('swords-07', 'fi', 'Miekkojen seitsemän', 'Miekat', 'Strategia, petos ja hiljaa poistuminen. Hahmo hiipii pois mukanaan viisi miekkaa, kaksi jää taakse — joskus täytyy toimia hiljaa saadaksesi tarvitsemasi.'),
  ('swords-08', 'en', 'Eight of Swords', 'Swords', 'Restriction, negative thoughts, and feeling trapped. Bound and blindfolded before eight swords, the figure reminds you that the cage is often one you build yourself.'),
  ('swords-08', 'fi', 'Miekkojen kahdeksan', 'Miekat', 'Rajoitukset, negatiiviset ajatukset ja vangittuna olemisen tunne. Sidottu ja silmät peitettynä kahdeksan miekan edessä hahmo muistuttaa, että häkki on usein itse rakentamasi.'),
  ('swords-09', 'en', 'Nine of Swords', 'Swords', 'Anxiety, worry, and sleepless nights. Sitting up in bed with nine swords on the wall, the figure shows how fear looms largest in the dark.'),
  ('swords-09', 'fi', 'Miekkojen yhdeksän', 'Miekat', 'Ahdistus, huoli ja unettomat yöt. Yhdeksän miekan kanssa seinällä istuva hahmo näyttää, miten pelko kasvaa suurimmaksi pimeässä.'),
  ('swords-10', 'en', 'Ten of Swords', 'Swords', 'Painful endings, deep wounds, and rock bottom. Pierced by ten swords at dawn — the darkest moment right before the light returns.'),
  ('swords-10', 'fi', 'Miekkojen kymmenen', 'Miekat', 'Kivuliaat päätökset, syvät haavat ja aallonpohja. Kymmenen miekan lävistämä aamunkoitteessa — pimein hetki juuri ennen valon paluuta.'),
  ('swords-page', 'en', 'Page of Swords', 'Swords', 'Vigilance, curiosity, and a sharp new idea. The page raises his sword — an eager mind hunting for truth and fresh perspectives.'),
  ('swords-page', 'fi', 'Miekkojen lähetti', 'Miekat', 'Valppaus, uteliaisuus ja terävä uusi idea. Lähetti kohottaa miekkansa — innokas mieli, joka etsii totuutta ja uusia näkökulmia.'),
  ('swords-knight', 'en', 'Knight of Swords', 'Swords', 'Ambition, action, and charging into battle. The knight gallops with his sword raised — swift and decisive, and sometimes reckless.'),
  ('swords-knight', 'fi', 'Miekkojen ritari', 'Miekat', 'Kunnianhimo, toiminta ja taisteluun rynnistäminen. Ritari laukkaa miekka koholla — nopea ja päättäväinen, ja joskus harkitsematon.'),
  ('swords-queen', 'en', 'Queen of Swords', 'Swords', 'Independence, clear boundaries, and honest intellect. Seated among the clouds with her sword, she is uncompromising truth — perceptive, fair, and direct.'),
  ('swords-queen', 'fi', 'Miekkojen kuningatar', 'Miekat', 'Itsenäisyys, selkeät rajat ja rehellinen äly. Pilvien keskellä miekkansa kanssa istuva Kuningatar on tinkimätöntä totuutta — tarkkanäköinen, oikeudenmukainen ja suora.'),
  ('swords-king', 'en', 'King of Swords', 'Swords', 'Authority, truth, and intellectual power. The king lifts his sword to the sky — reason and justice wielded with a steady, incorruptible hand.'),
  ('swords-king', 'fi', 'Miekkojen kuningas', 'Miekat', 'Auktoriteetti, totuus ja älyllinen voima. Miekkansa taivasta kohti kohottava Kuningas — järki ja oikeus, jota käytetään vakaalla, lahjomattomalla kädellä.'),
  ('pentacles-ace', 'en', 'Ace of Pentacles', 'Pentacles', 'A new financial opportunity and a material beginning. The hand from the cloud offers a golden pentacle — prosperity and security taking root.'),
  ('pentacles-ace', 'fi', 'Pentakeleiden ässä', 'Pentakelit', 'Uusi taloudellinen mahdollisuus ja materiaalinen alku. Pilvestä ojentuva käsi tarjoaa kultaista pentakelia — vauraus ja turvallisuus saavat alkunsa.'),
  ('pentacles-02', 'en', 'Two of Pentacles', 'Pentacles', 'Balance, adaptability, and juggling priorities. The figure dances with two pentacles linked by an infinity ribbon — keeping many things in motion at once.'),
  ('pentacles-02', 'fi', 'Pentakeleiden kaksi', 'Pentakelit', 'Tasapaino, sopeutumiskyky ja asioiden jonglööraus. Hahmo tanssii kahden äärettömyysnauhalla yhdistetyn pentakelin kanssa — monta asiaa liikkeellä yhtä aikaa.'),
  ('pentacles-03', 'en', 'Three of Pentacles', 'Pentacles', 'Teamwork, craftsmanship, and collaboration. The mason carves a cathedral arch while his client looks on — skill recognized and rewarded through cooperation.'),
  ('pentacles-03', 'fi', 'Pentakeleiden kolme', 'Pentakelit', 'Tiimityö, ammattitaito ja yhteistyö. Muurari veistää katedraalin kaarta, kun asiakas katsoo vierestä — taito tunnustetaan ja palkitaan yhteistyön kautta.'),
  ('pentacles-04', 'en', 'Four of Pentacles', 'Pentacles', 'Security, control, and holding on tightly. Pentacles clutched to crown, hands, and feet give stability — but at the cost of openness.'),
  ('pentacles-04', 'fi', 'Pentakeleiden neljä', 'Pentakelit', 'Turvallisuus, kontrolli ja tiukka ote. Kruunuun, käsiin ja jalkoihin puristetut pentakelit antavat vakautta — mutta avoimuuden kustannuksella.'),
  ('pentacles-05', 'en', 'Five of Pentacles', 'Pentacles', 'Hardship, loss, and feeling left out in the cold. Two figures pass a lit window in the snow — struggle is real, but shelter and help exist if you ask for them.'),
  ('pentacles-05', 'fi', 'Pentakeleiden viisi', 'Pentakelit', 'Vaikeudet, menetys ja ulkona kylmässä oleminen. Kaksi hahmoa kulkee lumessa valaistun ikkunan ohi — kamppailu on todellista, mutta suoja ja apu ovat olemassa, jos pyydät.'),
  ('pentacles-06', 'en', 'Six of Pentacles', 'Pentacles', 'Generosity, giving, and fair exchange. The merchant weighs coins on his scales, giving to those in need — charity and balanced reciprocity.'),
  ('pentacles-06', 'fi', 'Pentakeleiden kuusi', 'Pentakelit', 'Anteliaisuus, antaminen ja reilu vaihto. Kauppias punnitsee kolikoita vaa''allaan ja antaa tarvitseville — hyväntekeväisyys ja tasapainoinen vastavuoroisuus.'),
  ('pentacles-07', 'en', 'Seven of Pentacles', 'Pentacles', 'Patience, long-term view, and assessing progress. The farmer leans on his staff, surveying vines heavy with fruit — hard work is growing, but the harvest is not yet in.'),
  ('pentacles-07', 'fi', 'Pentakeleiden seitsemän', 'Pentakelit', 'Kärsivällisyys, pitkän tähtäimen näkymä ja edistyksen arviointi. Maanviljelijä nojaa sauvaansa ja katsoo hedelmää kantavia köynnöksiä — kova työ kasvaa, mutta sato ei ole vielä kypsynyt.'),
  ('pentacles-08', 'en', 'Eight of Pentacles', 'Pentacles', 'Apprenticeship, skill, and diligent practice. The artisan carves pentacles one by one — mastery comes from focused, repeated effort.'),
  ('pentacles-08', 'fi', 'Pentakeleiden kahdeksan', 'Pentakelit', 'Oppipoikana oleminen, taito ja ahkera harjoittelu. Käsityöläinen veistää pentakeleita yksi toisensa jälkeen — mestaruus syntyy keskittyneestä, toistuvasta työstä.'),
  ('pentacles-09', 'en', 'Nine of Pentacles', 'Pentacles', 'Luxury, self-sufficiency, and enjoying the fruits of labor. The woman walks her vineyard with a hooded falcon — independence and refined comfort.'),
  ('pentacles-09', 'fi', 'Pentakeleiden yhdeksän', 'Pentakelit', 'Ylellisyys, omavaraisuus ja työn hedelmistä nauttiminen. Nainen kävelee viinitarhassaan huppupäinen haukka olallaan — itsenäisyys ja hienostunut mukavuus.'),
  ('pentacles-10', 'en', 'Ten of Pentacles', 'Pentacles', 'Wealth, inheritance, and lasting legacy. A family beneath an archway of pentacles — prosperity shared across generations.'),
  ('pentacles-10', 'fi', 'Pentakeleiden kymmenen', 'Pentakelit', 'Varallisuus, perintö ja kestävä perintö. Perhe pentakeleilla koristellun kaaren alla — sukupolvelta toiselle jaettu vauraus.'),
  ('pentacles-page', 'en', 'Page of Pentacles', 'Pentacles', 'Ambition, practicality, and a new opportunity. The page studies his pentacle — a grounded approach to manifesting material goals.'),
  ('pentacles-page', 'fi', 'Pentakeleiden lähetti', 'Pentakelit', 'Kunnianhimo, käytännöllisyys ja uusi mahdollisuus. Lähetti tutkii pentakeliaan — maadoitettu lähestymistapa materiaalisten päämäärien toteuttamiseen.'),
  ('pentacles-knight', 'en', 'Knight of Pentacles', 'Pentacles', 'Hard work, routine, and dependable progress. The knight rides slowly across fertile fields — steady, methodical effort that reliably gets results.'),
  ('pentacles-knight', 'fi', 'Pentakeleiden ritari', 'Pentakelit', 'Kova työ, rutiinit ja luotettava edistyminen. Ritari ratsastaa hitaasti hedelmällisten peltojen halki — tasainen, määrätietoinen työ, joka tuottaa luotettavasti tulosta.'),
  ('pentacles-queen', 'en', 'Queen of Pentacles', 'Pentacles', 'Nurturing, practicality, and abundant comfort. Seated in her lush garden, she is a generous provider of material and emotional security.'),
  ('pentacles-queen', 'fi', 'Pentakeleiden kuningatar', 'Pentakelit', 'Hoivaavuus, käytännöllisyys ja runsas mukavuus. Rehevässä puutarhassaan istuva Kuningatar on antelias aineellisen ja emotionaalisen turvallisuuden tarjoaja.'),
  ('pentacles-king', 'en', 'King of Pentacles', 'Pentacles', 'Success, abundance, and material mastery. The king on his throne, the bull''s head on his pedestal — wealth and business acumen at their peak.'),
  ('pentacles-king', 'fi', 'Pentakeleiden kuningas', 'Pentakelit', 'Menestys, runsaus ja materiaalinen mestaruus. Valtikallaan istuva Kuningas, pedestaalillaan härän pää — vauraus ja liiketoimintaosaaminen huipussaan.');
